type Analytics = {
  pageViews: number
  uniqueVisitors: number
  bounceRate: number
}

type Notification = {
  id: number
  message: string
  read: boolean
}

type Settings = {
  theme: string
  emailNotifications: boolean
  language: string
}

async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return {
      analytics: analytics as Analytics,
      notifications: notifications as Notification[],
      settings: settings as Settings,
    }
  } catch {
    return {
      analytics: { pageViews: 0, uniqueVisitors: 0, bounceRate: 0 },
      notifications: [] as Notification[],
      settings: {
        theme: 'light',
        emailNotifications: true,
        language: 'en',
      },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  const unreadCount = notifications.filter((n) => !n.read).length

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page views: {analytics.pageViews.toLocaleString()}</p>
        <p>Unique visitors: {analytics.uniqueVisitors.toLocaleString()}</p>
        <p>Bounce rate: {analytics.bounceRate}%</p>
      </section>

      <section>
        <h3>Notifications ({unreadCount} unread)</h3>
        {notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((notification) => (
              <li key={notification.id}>
                {notification.message}
                {notification.read ? '' : ' (unread)'}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Email notifications: {settings.emailNotifications ? 'on' : 'off'}</p>
        <p>Language: {settings.language}</p>
      </section>
    </div>
  )
}

